@namespace sv_48c57e2e9a36468a9b3968241569d70b.Components.Chat

<li class="channel-item @(IsActive ? "active" : "")" @onclick="HandleClick">
    <div class="channel-name"># @Channel.Name</div>
    <div class="channel-desc">@TruncatedDescription</div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="unread-badge">@Channel.UnreadCount</span>
    }
</li>

@code {
    [Parameter, EditorRequired] public Services.Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<Services.Channel> OnSelected { get; set; }

    private string TruncatedDescription =>
        Channel.Description.Length > 40
            ? Channel.Description[..40] + "…"
            : Channel.Description;

    private async Task HandleClick() => await OnSelected.InvokeAsync(Channel);
}

@namespace sv_48c57e2e9a36468a9b3968241569d70b.Components.Chat

<aside class="channel-sidebar">
    <h3 class="sidebar-title">Channels</h3>
    <ul class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </ul>
</aside>

@code {
    [Parameter, EditorRequired] public List<Services.Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<Services.Channel> OnChannelSelected { get; set; }
}

@namespace sv_48c57e2e9a36468a9b3968241569d70b.Components.Chat

<div class="message-input">
    <textarea @bind="Text"
              @bind:event="oninput"
              @onkeydown="HandleKeyDown"
              placeholder="@Placeholder"
              rows="2"></textarea>
    <button class="btn-send" @onclick="HandleSend" disabled="@string.IsNullOrWhiteSpace(Text)">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private string Text { get; set; } = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await HandleSend();
        }
    }

    private async Task HandleSend()
    {
        if (string.IsNullOrWhiteSpace(Text)) return;
        var content = Text.Trim();
        Text = "";
        await OnSubmit.InvokeAsync(content);
    }
}

@namespace sv_48c57e2e9a36468a9b3968241569d70b.Components.Chat

<div class="message-item" @onmouseenter="() => _hovered = true" @onmouseleave="() => { _hovered = false; _showEmojiPicker = false; }">
    <div class="message-header">
        <strong class="message-author">@Message.Author</strong>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reaction-row">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => HandleReaction(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (_hovered)
    {
        <div class="message-actions">
            <button class="action-btn" title="Reply" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">💬</button>
            <button class="action-btn" title="React" @onclick="ToggleEmojiPicker">😀</button>
        </div>

        @if (_showEmojiPicker)
        {
            <div class="emoji-picker">
                @foreach (var emoji in _commonEmojis)
                {
                    <button class="emoji-option" @onclick="() => HandleReaction(emoji)">@emoji</button>
                }
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public Services.Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool _hovered;
    private bool _showEmojiPicker;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private void ToggleEmojiPicker() => _showEmojiPicker = !_showEmojiPicker;

    private async Task HandleReaction(string emoji)
    {
        _showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@namespace sv_48c57e2e9a36468a9b3968241569d70b.Components.Chat
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-list" @ref="_scrollContainer">
    @if (_loadingOlder)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }
    @if (!HasMoreMessages && Messages.Count > 0)
    {
        <div class="beginning-indicator">Beginning of conversation</div>
    }
    @foreach (var msg in Messages)
    {
        <MessageItem Message="msg"
                     ReplyCount="GetReplyCount(msg.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; } = true;
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference _scrollContainer;
    private IJSObjectReference? _scrollModule;
    private DotNetObjectReference<MessageList>? _dotNetRef;
    private bool _loadingOlder;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _scrollModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Chat/MessageList.razor.js");
            await _scrollModule.InvokeVoidAsync("initScrollObserver", _scrollContainer, _dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_loadingOlder || !HasMoreMessages) return;
        _loadingOlder = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _loadingOlder = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_scrollModule is not null)
        {
            try { await _scrollModule.InvokeVoidAsync("dispose"); } catch (JSDisconnectedException) { }
            await _scrollModule.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

let observer = null;
let sentinel = null;

export function initScrollObserver(container, dotNetRef) {
    // Create a sentinel element at the top of the scroll container
    sentinel = document.createElement('div');
    sentinel.style.height = '1px';
    container.prepend(sentinel);

    observer = new IntersectionObserver(
        (entries) => {
            if (entries[0].isIntersecting) {
                dotNetRef.invokeMethodAsync('OnScrolledToTop');
            }
        },
        { root: container, threshold: 0.1 }
    );
    observer.observe(sentinel);

    // Scroll to bottom initially
    container.scrollTop = container.scrollHeight;
}

export function dispose() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
    if (sentinel) {
        sentinel.remove();
        sentinel = null;
    }
}

@namespace sv_48c57e2e9a36468a9b3968241569d70b.Components.Chat

<section class="message-area">
    @if (CurrentChannel is not null)
    {
        <header class="area-header">
            <h2># @CurrentChannel.Name</h2>
            <p>@CurrentChannel.Description</p>
        </header>

        <MessageList Messages="Messages"
                     ThreadReplyCounts="ThreadReplyCounts"
                     HasMoreMessages="HasMoreMessages"
                     OnLoadMore="OnLoadMore"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />

        <MessageInput Placeholder="Message #@CurrentChannel.Name"
                      ButtonLabel="Send"
                      OnSubmit="OnSendMessage" />
