@namespace sv_48c57e2e9a36468a9b3968241569d70b.Components.Chat
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-list" @ref="_scrollContainer">
    @if (_loadingOlder)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }
    @if (!HasMoreMessages && Messages.Count > 0)
    {
        <div class="beginning-indicator">Beginning of conversation</div>
    }
    @foreach (var msg in Messages)
    {
        <MessageItem Message="msg"
                     ReplyCount="GetReplyCount(msg.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; } = true;
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference _scrollContainer;
    private IJSObjectReference? _scrollModule;
    private DotNetObjectReference<MessageList>? _dotNetRef;
    private bool _loadingOlder;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _scrollModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Chat/MessageList.razor.js");
            await _scrollModule.InvokeVoidAsync("initScrollObserver", _scrollContainer, _dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_loadingOlder || !HasMoreMessages) return;
        _loadingOlder = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _loadingOlder = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_scrollModule is not null)
        {
            try { await _scrollModule.InvokeVoidAsync("dispose"); } catch (JSDisconnectedException) { }
            await _scrollModule.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

