}

/* ───────── Message List ───────── */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .loading-indicator,
::deep .beginning-indicator {
    text-align: center;
    color: #72767d;
    font-size: 0.8rem;
